<template><div v-if="open" class="fixed inset-0 z-50 bg-slate-950/50 flex items-center justify-center p-4" @click.self="$emit('close')"><form class="w-full max-w-2xl max-h-[90vh] overflow-auto rounded-2xl bg-white p-6 space-y-4" @submit.prevent="submit"><div class="flex justify-between"><h2 class="text-xl font-bold">Tambah Lelang</h2><button type="button" @click="$emit('close')">✕</button></div><div><label class="label">Judul</label><input v-model="form.title" class="input" required/></div><div><label class="label">Deskripsi</label><MarkdownEditor v-model="form.description"/></div><div class="grid sm:grid-cols-2 gap-4"><div><label class="label">Harga Awal</label><input v-model.number="form.start_bid" class="input" type="number" min="1" required/></div><div><label class="label">Batas Waktu</label><input v-model="form.closed_at" class="input" type="datetime-local" required/></div></div><button class="btn-primary" :disabled="loading">{{loading?'Menyimpan...':'Simpan Lelang'}}</button></form></div></template>
<script setup>import {reactive,watch} from 'vue';import MarkdownEditor from '../components/MarkdownEditor.vue';const props=defineProps({open:Boolean,loading:Boolean});const emit=defineEmits(['close','submit']);const form=reactive({title:'',description:'',start_bid:1000,closed_at:''});watch(()=>props.open,v=>{if(v)Object.assign(form,{title:'',description:'',start_bid:1000,closed_at:''})});function submit(){const d=new Date(form.closed_at);const closed_at=d.toISOString().slice(0,19).replace('T',' ');emit('submit',{...form,closed_at})}</script>
